10	async function fetchAllPages(
11	  endpointPath: string,
12	  apiKey: string,
13	): Promise<{ tier: string; intelligenceIndexVersion: number; rows: unknown[] }> {
14	  const rows: unknown[] = [];
15	  let page = 1;
16	  let tier = "";
17	  let intelligenceIndexVersion = 0;
18	
19	  while (true) {
20	    const url = `${API_BASE}${endpointPath}?page=${page}`;
21	    const res = await fetch(url, { headers: { "x-api-key": apiKey } });
22	
23	    if (!res.ok) {
24	      const body = await res.text();
25	      throw Object.assign(new Error(`${res.status} ${res.statusText} on ${url}: ${body}`), {
26	        status: res.status,
27	      });
28	    }
29	
30	    const json = await res.json();
31	    tier = json.tier;
32	    intelligenceIndexVersion = json.intelligence_index_version;
33	    rows.push(...json.data);
34	
35	    if (!json.pagination?.has_more) break;
36	    page += 1;
37	  }
38	
39	  return { tier, intelligenceIndexVersion, rows };
40	}
